const filterRoot=document.querySelector('.filters');const advanced=document.createElement('details');advanced.className='advanced-filters';advanced.innerHTML='<summary title="Открыть дополнительные фильтры">☰ Ещё фильтры</summary><div class="advanced-menu"></div>';filterRoot.append(advanced);const advancedMenu=advanced.querySelector('.advanced-menu');for(const node of [document.querySelector('#origin').closest('label'),document.querySelector('#leg-filter'),document.querySelector('#recipient').closest('label'),document.querySelector('#util-limit').closest('label'),document.querySelector('#hub-filter')])advancedMenu.append(node);filterRoot.insertAdjacentHTML('afterend','<div id="main-filter-chips" class="main-filter-chips" aria-label="Действующие фильтры"></div>');
const selectedRc=new Set();let rcOptions=[],rcDirectory=new Map();const rcNorm=s=>String(s||'').trim().replace(/\s+/g,' ').toLowerCase().replace(/ё/g,'е');const rcSelect=document.querySelector('#network-rc'),rcLabel=rcSelect.closest('label');rcLabel.hidden=true;rcLabel.insertAdjacentHTML('afterend','<details id="rc-picker" class="rc-picker"><summary title="Выбрать адреса клиентов">РЦ: все</summary><div class="rc-menu"><input id="rc-search" type="search" placeholder="Клиент, город, район, адрес или код" aria-label="Поиск адресов"><div id="rc-list"></div></div></details>');
const rcPicker=document.querySelector('#rc-picker'),rcMenu=rcPicker.querySelector('.rc-menu'),contentGrid=document.querySelector('.shell > .grid');rcMenu.hidden=true;rcMenu.insertAdjacentHTML('afterbegin','<div class="rc-panel-head"><strong>Адреса клиентов</strong><button type="button" id="rc-panel-close" title="Закрыть список РЦ">✕</button></div>');contentGrid.append(rcMenu);rcPicker.addEventListener('toggle',()=>{rcMenu.hidden=!rcPicker.open;contentGrid.classList.toggle('rc-open',rcPicker.open);if(map)requestAnimationFrame(()=>map.invalidateSize());if(rcPicker.open)drawRcPicker();if(rcPicker.open&&window.matchMedia('(max-width: 800px)').matches)rcMenu.scrollIntoView({behavior:'smooth',block:'start'})});document.querySelector('#rc-panel-close').addEventListener('click',()=>{rcPicker.open=false});
function rcPeriodStats(){const from=document.querySelector('#from').value,to=document.querySelector('#to').value,network=document.querySelector('#network').value,rows=all.filter(r=>r.start&&r.start>=from&&r.start<=to&&(!network||r.receiver===network)),counts=new Map(),stats=new Map();for(const r of rows)if(r.trip&&r.operation){const k=r.trip+'|'+r.operation;counts.set(k,(counts.get(k)||0)+1)}for(const r of rows){const key=rcKey(r);if(!stats.has(key))stats.set(key,{trips:new Set(),weight:0,boxes:0,weights:0,boxRows:0,missingWeight:0,missingBoxes:0});const v=stats.get(key),unique=r.trip&&r.operation&&counts.get(r.trip+'|'+r.operation)===1;if(r.trip)v.trips.add(r.trip);if(unique&&r.weight!=null&&r.weight>=0){v.weight+=r.weight;v.weights++}else v.missingWeight++;if(unique&&r.qty!=null&&r.qty>=0&&['КОР','КОРОБ','КОРОБКА'].includes(String(r.uom||'').trim().toUpperCase())){v.boxes+=r.qty;v.boxRows++}else v.missingBoxes++}return stats;}
function drawRcPicker(){const stats=rcPeriodStats(),picker=document.querySelector('#rc-picker'),search=document.querySelector('#rc-search').value.trim().toLocaleLowerCase('ru');picker.querySelector('summary').textContent=selectedRc.size?'Адреса: '+selectedRc.size:'＋ Адреса';picker.querySelector('summary').title='Выбрать города, районы или адреса клиентов';const cities=new Map();for(const [index,o] of rcOptions.entries()){if(search&&!`${o.city} ${o.district} ${o.id} ${o.address} ${o.receiver}`.toLocaleLowerCase('ru').includes(search))continue;if(!cities.has(o.city))cities.set(o.city,new Map());const districts=cities.get(o.city);if(!districts.has(o.district))districts.set(o.district,[]);districts.get(o.district).push({index,...o})}const selections=[],groupCell=(items,label,rows)=>{const i=selections.push(items)-1;return `<td rowspan="${rows}" class="rc-group-cell"><label><input type="checkbox" data-group="${i}" ${items.every(o=>selectedRc.has(o.key))?'checked':''} aria-label="Выбрать ${esc(label)}"> ${esc(label)}</label></td>`};let body='';for(const [city,districts] of [...cities].sort((a,b)=>a[0].localeCompare(b[0],'ru'))){const sorted=[...districts].sort((a,b)=>a[0].localeCompare(b[0],'ru')),cityItems=sorted.flatMap(([,items])=>items);let firstCity=true;for(const [district,items] of sorted){items.sort((a,b)=>a.address.localeCompare(b.address,'ru'));let firstDistrict=true;for(const o of items){body+='<tr>';if(firstCity){body+=groupCell(cityItems,city,cityItems.length);firstCity=false}if(firstDistrict){body+=groupCell(items,district,items.length);firstDistrict=false}const stat=stats.get(o.key),trips=stat?.trips.size||0,weight=stat?.weights?numberText(stat.weight/1000)+(stat.missingWeight?' *':''):'—',boxes=stat?.boxRows?numberText(stat.boxes)+(stat.missingBoxes?' *':''):'—';body+=`<td class="rc-check-cell"><input type="checkbox" class="rc-item" data-index="${o.index}" ${selectedRc.has(o.key)?'checked':''} aria-label="Выбрать ${esc(o.address||o.id)}"></td><td title="Район: ${esc(o.method)}">${esc(o.address||'адрес не указан')}<br><span class="rc-recipient">${esc(o.receiver||'Клиент не указан')}</span></td><td>${esc(o.id||'—')}</td><td class="rc-metric">${trips}</td><td class="rc-metric">${weight}</td><td class="rc-metric">${boxes}</td></tr>`}}}document.querySelector('#rc-list').innerHTML='<div class="rc-actions"><button type="button" id="rc-clear">Все адреса / сброс</button><span>Выбрано: '+selectedRc.size+'</span></div><p class="rc-period-note">За период по дате начала BLC. * — данные неполные; вес и короба только по однозначным операциям.</p><table class="rc-table"><thead><tr><th>Город</th><th>Район</th><th>✓</th><th>Адрес</th><th>Код</th><th>Рейсы</th><th>Тонны</th><th>Короба</th></tr></thead><tbody>'+(body||'<tr><td colspan="8">Адреса не найдены</td></tr>')+'</tbody></table>';picker._groups=selections;}

document.querySelector('#rc-search').addEventListener('input',drawRcPicker);document.querySelector('#rc-list').addEventListener('change',e=>{const input=e.target;if(input.matches('.rc-item')){const key=rcOptions[Number(input.dataset.index)].key;input.checked?selectedRc.add(key):selectedRc.delete(key)}else if(input.matches('[data-group]')){const items=document.querySelector('#rc-picker')._groups[Number(input.dataset.group)];for(const item of items)input.checked?selectedRc.add(item.key):selectedRc.delete(item.key)}else return;selection=null;drawRcPicker();update()});document.querySelector('#rc-list').addEventListener('click',e=>{if(e.target.id==='rc-clear'){selectedRc.clear();selection=null;drawRcPicker();update()}});

const selectedHubs=new Set(),selectedLegs=new Set();
