function refreshRc(){const network=document.querySelector('#network').value,sel=document.querySelector('#network-rc');sel.disabled=false;sel.innerHTML='<option value="">Все РЦ</option>';selectedRc.clear();rcOptions=[];document.querySelector('#rc-search').value='';const points=new Map();for(const r of all.filter(r=>!network||r.receiver===network)){if(!r.recipient_id&&!r.address)continue;const address=String(r.address||'').trim(),source=rcDirectory.get(JSON.stringify([chain,rcNorm(r.receiver),rcNorm(address)])),city=source?.city||r.destination||'Город не указан',district=source?.district||city,key=rcKey(r);points.set(key,{key,city,district,id:r.recipient_id||'',address:address||source?.office_address||'',receiver:r.receiver||'',method:source?.district?(source?.method||'нет данных'):'Район не определён; указан город'})}rcOptions=[...points.values()].sort((a,b)=>a.city.localeCompare(b.city,'ru')||a.address.localeCompare(b.address,'ru'));drawRcPicker();}

