const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const city=s=>cities[String(s||'').trim().toLowerCase()];
function endpoint(name,leg,side){if(String(name||'').trim().toLowerCase()==='снкт')return {label:'СНКТ · Благовещенск (район границы)',coords:[50.29,127.528]};if(String(name||'').trim().toLowerCase()==='алабино')return {label:'Алабино · Московская область',coords:[55.5254,37.001]};if(String(name||'').trim().toLowerCase()==='комсомольск')return {label:'Комсомольск-на-Амуре',coords:[50.55,137.007]};const part=String(leg||'').split(/\s*[-–—]\s*/)[side]||'';const kind=/^хаб/i.test(part)?'hub':/^филиал/i.test(part)?'branch':'unknown';if(String(name||'').trim().toLowerCase()==='москва'){if(kind==='hub')return {label:'Москва · хаб (район Дмитрова)',coords:[56.3477,37.5203]};if(kind==='branch')return {label:'Москва · филиалы',coords:city(name)};}return {label:name,coords:city(name)};}
// City centres are approximate; address text is the evidence, not a geocoded warehouse location.
const recipientCities=[[/чехов/i,'Чехов',[55.147,37.454]],[/копейск/i,'Копейск',[55.117,61.618]],[/среднеуральск/i,'Среднеуральск',[56.99,60.477]],[/лобня/i,'Лобня',[56.012,37.475]],[/пушкино/i,'Пушкино',[56.01,37.849]],[/солнечногорск/i,'Солнечногорск',[56.185,36.978]],[/ногинск/i,'Ногинск',[55.853,38.442]],[/раменск/i,'Раменское',[55.566,38.23]],[/подольск/i,'Подольск',[55.431,37.545]],[/серпухов/i,'Серпухов',[54.915,37.411]],[/дмитровск/i,'Дмитровский район',[56.3477,37.5203]],[/видное/i,'Видное',[55.552,37.709]],[/новоалтайск/i,'Новоалтайск',[53.411,83.932]]];
function destinationPoint(r){if(/^новгород$/i.test(String(r.destination||'').trim())&&/^новгород_ф$/i.test(String(r.receiver||'').trim()))return {label:'Великий Новгород · филиал',coords:[58.521,31.275]};if(!String(r.destination||'').trim()){const address=r.address||'';for(const [pattern,name,coords] of [[/минск/i,'Минск',[53.9,27.567]],[/тбилиси/i,'Тбилиси',[41.715,44.827]],[/ташкент/i,'Ташкент',[41.299,69.241]]])if(pattern.test(address))return {label:name+' · по адресу (оценка)',coords};}if(/кочкин/i.test(r.address||'')&&/логистическ/i.test(r.address||'')){const street=(r.address.match(/(?:д(?:ом)?\.?|стр\.?)[\s№.]*([125])(?:\D|$)/i)||[])[1];return {label:'Кочкин · '+(r.receiver||'РЦ')+(street?' · Логистическая, '+street:'')+' (район, оценка)',coords:[44.873404,39.180632]};}if(/^дзержинск$/i.test(r.destination||'')&&/нижегородск/i.test(r.address||''))return {label:'Дзержинск · Нижегородская область',coords:[56.244,43.455]};if(!/^хаб\s*[-–—]\s*сеть$/i.test(r.leg||''))return endpoint(r.destination,r.leg,1);const matches=recipientCities.filter(([pattern])=>pattern.test(r.address||''));if(matches.length===1){const [,name,coords]=matches[0];return {label:name+' · район РЦ (оценка)',coords};}return endpoint(r.destination,r.leg,1);}
function routeKey(r){return JSON.stringify([r.origin,r.destination,r.leg,destinationPoint(r).label]);}
function rowHubs(r){const parts=String(r.leg||'').split(/\s*[-–—]\s*/);const hubs=[];if(/^хаб$/i.test((parts[0]||'').trim())&&r.origin)hubs.push(r.origin);if(/^хаб$/i.test((parts[1]||'').trim())&&r.destination)hubs.push(r.destination);return hubs;}
function originKind(leg){const part=String(leg||'').split(/\s*[-–—]\s*/)[0].trim();return /^хаб/i.test(part)?'С хаба':part?'Не с хаба':'Не определено';}
document.querySelector('#routes').closest('section').insertAdjacentHTML('afterend',`<section class="panel" id="trip-panel"><div class="top"><div><h2>Рейсы и точки</h2><p id="selection-label" class="note"></p></div><button id="clear-selection" title="Показать все рейсы по текущим фильтрам">Сбросить выбор на карте</button></div><p class="note">Выберите направление или город на карте, отметьте несколько рейсов либо откройте один рейс. Фактическая дата сдачи показана по получателю. Связь с заказом для отображения рейса не требуется. Вес — сумма строк BLC при уникальных номерах операций; стоимость относится к рейсу.</p><div class="tablewrap"><table><thead><tr><th>Выбор</th><th>Рейс</th><th>Маршрут SAP</th><th>Откуда → куда</th><th>Отправление</th><th>Начало</th><th>Точки</th><th>Вес, кг</th><th>Утилизация</th><th>Стоимость рейса</th><th>Расстояние</th></tr></thead><tbody id="trips"></tbody></table></div><div id="trip-details"></div></section>`);
document.querySelector('#trip-panel').insertAdjacentHTML('beforebegin',`<section class="panel" id="map-coverage"><h2>Контроль полноты карты</h2><p class="note">Учтены строки текущей цепи и выбранных фильтров. Рейс считается частично показанным, если хотя бы одно направление отображено, а другое — нет. Рейсы без даты начала не входят в выбранный период; записи без номера рейса показаны отдельно. Направления с одинаковыми координатами отображаются кольцом вокруг точки. Доступность фоновых тайлов не проверяется.</p><p id="coverage-summary"></p><details><summary>Показать рейсы с отсутствующими направлениями</summary><div class="tablewrap"><table><thead><tr><th>Рейс</th><th>Откуда → куда</th><th>Причина</th><th>На карте</th></tr></thead><tbody id="coverage-rows"></tbody></table></div></details></section>`);
