const mapStage=document.createElement('div');mapStage.className='map-stage';const mapElement=document.querySelector('#map');mapElement.before(mapStage);mapStage.append(mapElement);mapStage.insertAdjacentHTML('beforeend',`<aside id="map-analytics" class="map-analytics" hidden><div class="analytics-header"><strong>Аналитика</strong><button type="button" id="analytics-close" title="Закрыть аналитику">✕</button></div><label>Разрез <select id="analytics-mode"><option value="city">По городам назначения</option><option value="route">По направлениям</option><option value="client">По клиентам</option></select></label><p class="note">Текущие фильтры; рейсы — уникальные в группе. Вес и короба — строки BLC с уникальным номером операции; неполные данные не включены. Утилизация — средняя по доступным рейсам. Один рейс может входить в несколько групп. * — данные неполные; подробности при наведении.</p><div class="analytics-table"><table><thead><tr><th title="Выбрать строки">✓</th><th>Группа</th><th>Рейсы</th><th>Тонны</th><th>Короба</th><th>Утил.</th></tr></thead><tbody id="analytics-rows"></tbody><tfoot id="analytics-total"></tfoot></table></div></aside>`);
