let analyticsData=[];const selectedAnalytics=new Set();function openAnalytics(mode){document.querySelector('#analytics-mode').value=mode;document.querySelector('#point-inbound').hidden=true;document.querySelector('#map-analytics').hidden=false;analyticsMenu.open=false;renderAnalytics();if(map)requestAnimationFrame(()=>map.invalidateSize())}
analyticsMenu.addEventListener('click',e=>{const b=e.target.closest('[data-mode]');if(b)openAnalytics(b.dataset.mode)});document.querySelector('#analytics-mode').addEventListener('change',()=>{selectedAnalytics.clear();renderAnalytics()});document.querySelector('#analytics-close').addEventListener('click',()=>{document.querySelector('#map-analytics').hidden=true;if(map)requestAnimationFrame(()=>map.invalidateSize())});
function renderAnalytics(){const panel=document.querySelector('#map-analytics');if(panel.hidden)return;const mode=document.querySelector('#analytics-mode').value,groups=new Map();for(const r of analyticsData){const target=destinationPoint(r).label||'Не указан',cityName=target.split(' · ')[0],name=mode==='city'?cityName:mode==='route'?`${endpoint(r.origin,r.leg,0).label||'Не указан'} → ${target}`:(r.receiver||'Клиент не указан');if(!groups.has(name))groups.set(name,{trips:new Set(),operations:new Map(),missing:0});const g=groups.get(name);if(r.trip)g.trips.add(r.trip);const op=r.trip&&r.operation?r.trip+'|'+r.operation:null;if(!op){g.missing++;continue}if(!g.operations.has(op))g.operations.set(op,[]);g.operations.get(op).push(r)}const out=[...groups].map(([name,g])=>{let weight=0,boxes=0,weights=0,boxOps=0;for(const rows of g.operations.values()){if(rows.length!==1)continue;const r=rows[0];if(r.weight!=null&&r.weight>=0){weight+=r.weight;weights++}if(r.qty!=null&&r.qty>=0&&['КОР','КОРОБ','КОРОБКА'].includes(String(r.uom||'').trim().toUpperCase())){boxes+=r.qty;boxOps++}}const utils=[...g.trips].map(id=>tripData(id).util).filter(x=>x!=null&&Number.isFinite(x));return {name,trips:g.trips.size,weight,boxes,weights,boxOps,total:g.operations.size+g.missing,util:utils.length?utils.reduce((a,b)=>a+b,0)/utils.length:null,utilCount:utils.length}}).sort((a,b)=>b.trips-a.trips||a.name.localeCompare(b.name,'ru'));document.querySelector('#analytics-rows').innerHTML=out.map((g,i)=>`<tr><td><input type="checkbox" class="analytics-select" data-index="${i}" ${selectedAnalytics.has(g.name)?'checked':''} aria-label="Выбрать ${esc(g.name)}"></td><td>${esc(g.name)}</td><td>${g.trips}</td><td title="Учтено операций: ${g.weights} из ${g.total}">${g.weights?numberText(g.weight/1000)+(g.weights<g.total?' *':''):'—'}</td><td title="Учтено операций: ${g.boxOps} из ${g.total}">${g.boxOps?numberText(g.boxes)+(g.boxOps<g.total?' *':''):'—'}</td><td title="Утилизация известна для ${g.utilCount} из ${g.trips} рейсов">${g.util==null?'—':numberText(g.util)+'%'+(g.utilCount<g.trips?' *':'')}</td></tr>`).join('')||'<tr><td colspan="6">По выбранным фильтрам данных нет</td></tr>';document.querySelectorAll('.analytics-select').forEach(el=>el.addEventListener('change',()=>{const name=out[Number(el.dataset.index)].name;el.checked?selectedAnalytics.add(name):selectedAnalytics.delete(name);renderAnalytics()}));
const globalCounts=new Map();for(const r of analyticsData)if(r.trip&&r.operation){const k=r.trip+'|'+r.operation;globalCounts.set(k,(globalCounts.get(k)||0)+1)}const summarize=rows=>{const trips=new Set(),ops=new Map();for(const r of rows){if(r.trip)trips.add(r.trip);if(!r.trip||!r.operation)continue;const k=r.trip+'|'+r.operation;if(!ops.has(k))ops.set(k,[]);ops.get(k).push(r)}let weight=0,boxes=0,w=0,b=0;for(const [k,rs] of ops){if(rs.length!==1||globalCounts.get(k)!==1)continue;const r=rs[0];if(r.weight!=null&&r.weight>=0){weight+=r.weight;w++}if(r.qty!=null&&r.qty>=0&&['КОР','КОРОБ','КОРОБКА'].includes(String(r.uom||'').trim().toUpperCase())){boxes+=r.qty;b++}}return {trips:trips.size,weight,boxes,w,b}};
const key=r=>{const target=destinationPoint(r).label||'Не указан';return mode==='city'?target.split(' · ')[0]:mode==='route'?`${endpoint(r.origin,r.leg,0).label||'Не указан'} → ${target}`:(r.receiver||'Клиент не указан')};const total=summarize(analyticsData),chosen=summarize(analyticsData.filter(r=>selectedAnalytics.has(key(r)))),pct=(x,y)=>y?numberText(x/y*100)+'%':'—';document.querySelector('#analytics-total').innerHTML=`<tr><th colspan="2">Итого по выборке</th><th>${total.trips}</th><th>${total.w?numberText(total.weight/1000):'—'}</th><th>${total.b?numberText(total.boxes):'—'}</th><th>—</th></tr><tr><th colspan="2">Выбрано / доля</th><th>${chosen.trips} / ${pct(chosen.trips,total.trips)}</th><th>${chosen.w?numberText(chosen.weight/1000):'—'} / ${pct(chosen.weight,total.weight)}</th><th>${chosen.b?numberText(chosen.boxes):'—'} / ${pct(chosen.boxes,total.boxes)}</th><th>—</th></tr>`;}
mapStage.insertAdjacentHTML('beforeend',`<aside id="point-inbound" class="map-analytics" hidden><div class="analytics-header"><strong id="inbound-title">Входящие рейсы</strong><button type="button" id="inbound-close" title="Закрыть список">✕</button></div><p class="note">Группировка по фактической дате сдачи. Товары сопоставляются по номеру рейса и операции BLC.</p><div class="analytics-table inbound-table"><table><thead><tr><th>Фактическая дата сдачи</th><th>Рейс</th><th>Откуда</th><th>Товар</th></tr></thead><tbody id="inbound-rows"></tbody></table><div id="inbound-goods"></div></div></aside>`);
let inboundDetailsPromise=null,inboundRequest=0;function openInbound(n){selection={type:'city',value:n,direction:'in'};selectedTrips.clear();document.querySelector('#map-analytics').hidden=true;document.querySelector('#point-inbound').hidden=false;document.querySelector('#inbound-goods').innerHTML='';update();if(map)requestAnimationFrame(()=>map.invalidateSize())}
function renderInbound(){const panel=document.querySelector('#point-inbound');if(panel.hidden)return;if(selection?.type!=='city'||selection.direction!=='in'){panel.hidden=true;inboundRequest++;if(map)requestAnimationFrame(()=>map.invalidateSize());return}inboundRequest++;document.querySelector('#inbound-goods').innerHTML='';document.querySelector('#inbound-title').textContent='Входящие · '+(selection?.type==='city'?selection.value:'текущая выборка');const grouped=new Map();for(const r of analyticsData){if(!r.trip)continue;for(const date of (blcDates(r).length?blcDates(r):[''])){const key=JSON.stringify([date,r.trip]);if(!grouped.has(key))grouped.set(key,{id:r.trip,date,origins:new Set(),ops:new Set()});const g=grouped.get(key);g.origins.add(r.sender||r.origin||'не указано');if(r.operation)g.ops.add(r.operation)}}const rows=[...grouped.values()].sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')||a.id.localeCompare(b.id));document.querySelector('#inbound-rows').innerHTML=rows.map((r,i)=>`<tr><td>${esc(r.date||'не указана')}</td><td>${esc(r.id)}</td><td>${esc([...r.origins].join(', '))}</td><td><button class="inbound-open" data-index="${i}" title="Показать товар для этой точки и даты">Товары</button></td></tr>`).join('')||'<tr><td colspan="4">Рейсы не найдены</td></tr>';document.querySelectorAll('.inbound-open').forEach(button=>button.addEventListener('click',async()=>{const r=rows[Number(button.dataset.index)],box=document.querySelector('#inbound-goods'),request=++inboundRequest;box.textContent='Загружаем товары…';try{if(!inboundDetailsPromise)inboundDetailsPromise=fetch('../data/trip_details.json').then(x=>{if(!x.ok)throw Error('HTTP '+x.status);return x.json()}).catch(e=>{inboundDetailsPromise=null;throw e});const db=await inboundDetailsPromise;if(request!==inboundRequest||panel.hidden)return;const goods=(db[r.id]?.goods||[]).filter(g=>g.operation&&r.ops.has(g.operation));box.innerHTML=`<h4>Рейс ${esc(r.id)} · ${esc(r.date||'дата не указана')}</h4><p class="note">Товары только по совпавшим операциям BLC выбранной точки. Количества не пересчитываются между единицами.</p><div class="tablewrap"><table><thead><tr><th>Товар</th><th>Количество</th><th>Поставка / BLC</th></tr></thead><tbody>${goods.map(g=>`<tr><td>${esc(g.material||'—')} · ${esc(g.name||'—')}</td><td>${g.quantity==null?'—':numberText(g.quantity)} ${esc(g.uom||'')}</td><td>${esc(g.delivery||'—')} / ${esc(g.operation||'—')}</td></tr>`).join('')||'<tr><td colspan="3">Совпадающие товарные строки не найдены</td></tr>'}</tbody></table></div>`;box.scrollIntoView({block:'nearest'})}catch(e){if(request===inboundRequest)box.textContent='Не удалось загрузить товары: '+e.message}}));}
document.querySelector('#inbound-close').addEventListener('click',()=>{inboundRequest++;document.querySelector('#point-inbound').hidden=true;if(map)requestAnimationFrame(()=>map.invalidateSize())});
const selectedTrips=new Set();
const tripCache=new Map();
function utilizationColor(value){if(value==null)return '#91a2ba';const t=Math.max(0,Math.min(1,(value-25)/75));return `rgb(${Math.round(192-175*t)}, ${Math.round(27+15*t)}, ${Math.round(27+103*t)})`}
function addArrow(line){const path=line.getElement();if(!path)return;const svg=path.ownerSVGElement;if(!svg)return;const ns='http://www.w3.org/2000/svg';let defs=svg.querySelector('defs');if(!defs){defs=document.createElementNS(ns,'defs');svg.prepend(defs)}if(!defs.querySelector('#sns-arrow')){const marker=document.createElementNS(ns,'marker');for(const [k,v] of Object.entries({id:'sns-arrow',viewBox:'0 0 10 10',refX:'9',refY:'5',markerWidth:'23',markerHeight:'23',markerUnits:'userSpaceOnUse',orient:'auto'}))marker.setAttribute(k,v);const tip=document.createElementNS(ns,'path');tip.setAttribute('d','M 1 0.8 L 9.4 5 L 1 9.2 L 2.8 5 z');tip.setAttribute('fill','context-stroke');tip.setAttribute('stroke','#fff');tip.setAttribute('stroke-width','0.9');marker.append(tip);defs.append(marker)}path.setAttribute('marker-mid','url(#sns-arrow)')}
function routeUtilization(g){const values=[...g.trips].map(id=>tripData(id).util).filter(v=>v!=null&&Number.isFinite(v));return {average:values.length?values.reduce((a,b)=>a+b,0)/values.length:null,count:values.length,total:g.trips.size}}
function routeMeans(g){const rows=[...g.trips].map(tripData);const average=key=>{const values=rows.map(r=>r[key]).filter(v=>v!=null&&Number.isFinite(v));return {value:values.length?values.reduce((a,b)=>a+b,0)/values.length:null,count:values.length}};return {weight:average('weight'),cost:average('cost')}}
function meanLabel(result,unit,total){return result.value==null?'нет данных':`${numberText(result.value)} ${unit} (${result.count} из ${total})`}
