const numberText=n=>Number(n).toLocaleString('ru',{maximumFractionDigits:2});
function tripData(id){if(tripCache.has(id))return tripCache.get(id);const rows=allChains.filter(r=>r.trip===id),ops=rows.map(r=>r.operation),unique=ops.every(Boolean)&&new Set(ops).size===ops.length;const points=new Map();for(const r of rows){const key=r.recipient_id||r.address||r.receiver;if(key&&!points.has(key))points.set(key,r)}const weights=rows.map(r=>r.weight);const weight=unique&&weights.every(x=>x!=null&&x>=0)?weights.reduce((a,b)=>a+b,0):null;const capacity=[...new Set(rows.map(r=>r.capacity).filter(Boolean))];const ton=capacity.length===1?capacity[0].match(/(?:до\s*)?(\d+(?:[.,]\d+)?)\s*тонн/i):null;const util=weight!=null&&ton&&Number(ton[1].replace(',','.'))>0?weight/(Number(ton[1].replace(',','.'))*1000)*100:null;const boxes=unique&&rows.every(r=>r.qty!=null&&r.qty>=0&&['КОР','КОРОБ','КОРОБКА'].includes(String(r.uom||'').trim().toUpperCase()))?rows.reduce((n,r)=>n+r.qty,0):null;const costs=[...new Set(rows.map(r=>r.trip_cost).filter(x=>x!=null))],dist=[...new Set(rows.map(r=>r.distance).filter(x=>x!=null))];const sapRoutes=[...new Set(rows.flatMap(r=>r.sap_routes||[]))].sort(),originKinds=[...new Set(rows.map(r=>originKind(r.leg)))];const routeNames={};for(const row of rows)for(const [code,names] of Object.entries(row.sap_route_names||{}))routeNames[code]=[...new Set([...(routeNames[code]||[]),...names])];const result={sapRoutes,routeNames,originKinds,rows,points:[...points.values()],weight,util,boxes,capacity,cost:costs.length===1?costs[0]:null,distance:dist.length===1?dist[0]:null,unique};tripCache.set(id,result);return result}
function routeTooltip(t,code){const names=t.routeNames[code]||[];return [code,...(names.length?names:['Полное название отсутствует']),t.cost==null?'Стоимость рейса: нет данных':'Стоимость рейса: '+numberText(t.cost)+' ₽','Стоимость относится к рейсу; отдельный тариф маршрута не подтверждён'].join('\n');}
function tripLocations(t){const pairs=new Map();for(const r of t.rows){const from=r.sender||r.origin||'нет данных',to=r.receiver||r.destination||'нет данных',address=r.address||'',key=JSON.stringify([from,to,address,r.recipient_id||'']);if(!pairs.has(key))pairs.set(key,{from,to,address,dates:new Set()});for(const date of blcDates(r))pairs.get(key).dates.add(date)}return [...pairs.values()].map(p=>`<div class="trip-place">${esc(p.from)} → ${esc(p.to)}${p.address?`<span class="trip-address">${esc(p.address)}</span>`:''}<span class="trip-dates">Фактическая дата сдачи: ${esc([...p.dates].sort().join(', ')||'нет данных')}</span></div>`).join('')||'нет данных';}

